insert into public.aos_zi_knowledge_entities_v1(entity_key,entity_type,canonical_name,aliases,parent_entity_key,source_key,page_start,page_end,canonical_summary,public_client,advisor_internal,owner_admin,clinical_restricted,system_reference,status,version)
values
('DOMAIN_FACIAL','DOMAIN','Dominio Facial',array['Facial']::text[],'ZI_SYSTEM','ZI_DOMAINS_20260827',2,5,'Imagen, presencia y armonía consciente; integra calidad cutánea, equilibrio estructural y regeneración.','El Dominio Facial trabaja imagen, presencia y armonía consciente. Zi Vital prioriza calidad de piel, equilibrio estructural y regeneración respetando rasgos, identidad y naturalidad.','Antes de recomendar herramientas, identifica si la conversación es sobre calidad cutánea, armonía estructural o regeneración. Eso orienta a Skin Signature, Harmony Design o BioRegen Face.','El dominio facial contiene tres enfoques diferenciados y debe evitar que el catálogo se comunique como procedimientos sueltos.','La evaluación de piel, rostro y tejido corresponde a la consulta médica; el bot o asesor no debe adjudicar un enfoque clínico definitivo por síntomas aislados.','{"summary":"Dominio Facial: imagen, presencia y armonía consciente. El documento prioriza salud cutánea, equilibrio estructural y regeneración biológica, respetando identidad y naturalidad.","approaches":["APP_SKIN_SIGNATURE","APP_HARMONY_DESIGN","APP_BIOREGEN_FACE"],"source_principles":["No perseguir rejuvenecimiento por rejuvenecer","Respetar rasgos, identidad y naturalidad","No todos los pacientes recorren todos los enfoques"]}'::jsonb,'ACTIVE','ZI_KNOWLEDGE_V1_20260827'),
('APP_SKIN_SIGNATURE','APPROACH','Skin Signature','{}'::text[],'DOMAIN_FACIAL','ZI_DOMAINS_20260827',2,3,'Enfoque facial orientado a calidad cutánea, salud, hidratación, densidad y luminosidad sin alterar estructuras.','Skin Signature es el enfoque facial centrado en calidad de piel, hidratación, luminosidad y estabilidad cutánea, sin buscar cambios estructurales del rostro.','Úsalo cuando el plan ya está orientado a calidad cutánea. El documento lo vincula con hidrofacial, peelings, Pink Glow, Dermapen, radiofrecuencia fraccionada y productos de cuidado domiciliario.','Es la base de la estética facial consciente dentro del documento y funciona como puerta de entrada o mantenimiento para distintos perfiles.','El documento recomienda valorar estado de la piel y contempla soporte con vitaminas y, en pacientes descritos como inflamados, detox. La necesidad individual debe validarse clínicamente.','{"summary":"Enfoque facial de calidad cutánea, salud y glow consciente.","domain":"DOMAIN_FACIAL","source_treatments":["Hidrofacial avanzado","Peelings médicos (PQ Age, Biorrepel)","Pink Glow (biorevitalizador)","Dermapen con activos","Radiofrecuencia fraccionada","Mascarillas regenerativas y secantes según biotipo"],"source_products":["Sensiclean","UltrAGlow","Hydrashield","Regushield","Sensishield","SkinRegeneration","Beauty Maker","Astaxantina","Lymdharial / Gotas, Pomada","Power 10 formula soak up helper 30 ml","Power 10 formula firefighter 30 ml","Power 10 formula pore lupin 30 ml","Power 10 formula cera guard 30 ml","Power 10 formula honeydew fairy 30 ml","Ultra eye contour","Serum acne control","Polvo enzimatico","Mascarilla coenzyme Q10 30gr","Esthemax enzyme powder 113","Cardo mariano 500 mg/120"],"source_benefits":["Mejora visible y progresiva de la calidad de piel","Disminución de inflamación y sensibilidad","Mayor duración de tratamientos posteriores","Menor necesidad de intervenciones invasivas"],"source_ideal_profile":["Pacientes jóvenes o primerizos","Personas que buscan verse mejor sin hacerse algo","Pacientes post armonización","Personas con piel dañada por estrés, sol o malos hábitos"],"source_recommendations":["Acompañar con vitaminas antioxidantes","En pacientes descritos como inflamados, iniciar con detox","Integrar como mantenimiento a largo plazo"],"source_bias":{"bias":"Esto es solo limpieza","correction":"Educar mostrando que la piel sana es infraestructura, no estética superficial"},"source_process":["Evaluación","Preparación (detox/vitaminas)","Hidrofacial","Protocolos específicos","Productos domiciliarios","Mantenimiento"],"source_objective":"Construir una piel fuerte, estable y luminosa que sostenga cualquier proceso facial futuro","source_terms_are_not_canonical_catalog_names":true}'::jsonb,'ACTIVE','ZI_KNOWLEDGE_V1_20260827'),
('APP_HARMONY_DESIGN','APPROACH','Harmony Design','{}'::text[],'DOMAIN_FACIAL','ZI_DOMAINS_20260827',3,4,'Enfoque facial de equilibrio estructural, expresión y soporte con criterio médico y moderación.','Harmony Design es el enfoque facial orientado a equilibrio estructural, expresión y soporte, buscando resultados naturales sin exagerar rasgos.','Explícalo como diseño médico del rostro, no como ''poner volumen''. El documento lo relaciona con ácido hialurónico, perfilamiento, labios, toxina, HIFU facial y enzimas para papada.','Su diferenciador estratégico es moderación, naturalidad y criterio frente a la sobrecorrección.','La selección de puntos, productos y dosis es médica. El documento indica evaluar calidad de piel y complementar con otros enfoques cuando corresponda.','{"summary":"Enfoque facial de equilibrio estructural, expresión y soporte.","domain":"DOMAIN_FACIAL","source_treatments":["Ácido hialurónico en puntos de anclaje","Perfilamiento facial y nasal","Labios (volumen, forma o hidratación)","Toxina botulínica estratégica","HIFU facial como complemento","Enzimas faciales (reducción de papada)"],"source_products":["Lifting-B","Hydrashield","Regushield","Sensishield","Perfect-F","Redu Fast","Zinc Premium","Lip balm 5g","Lymdharial / Gotas, Pomada","Beauty Maker","Astaxantina","Neuro Vital","Cardo mariano 500 mg/120"],"source_benefits":["Rostro más descansado y armónico","Expresión más suave y natural","Prevención de colapso facial futuro"],"source_ideal_profile":["Pacientes +30","Personas con gestos marcados o cansancio facial","Pacientes que buscan elegancia, no exageración"],"source_recommendations":["No iniciar sin evaluar calidad de piel","Complementar con Skin Signature o BioRegen Face"],"source_bias":{"bias":"Querer más volumen","correction":"Mostrar que el exceso envejece y resta elegancia"},"source_process":["Evaluación","Definición de puntos","Intervención mínima necesaria","Soporte vitamínico","Seguimiento"],"source_objective":"Restaurar equilibrio facial sin alterar identidad","source_terms_are_not_canonical_catalog_names":true}'::jsonb,'ACTIVE','ZI_KNOWLEDGE_V1_20260827'),
('APP_BIOREGEN_FACE','APPROACH','BioRegen Face','{}'::text[],'DOMAIN_FACIAL','ZI_DOMAINS_20260827',5,5,'Enfoque facial de regeneración, longevidad y sostén biológico con resultados progresivos y naturales.','BioRegen Face es el enfoque facial de regeneración y longevidad. Busca estimular procesos propios del tejido con resultados progresivos y naturales.','Posiciónalo como proceso de regeneración, no como relleno rápido. El documento lo vincula con bioestimuladores, exosomas, PDRN/polinucleótidos, PRP e hidrataciones profundas.','Representa la filosofía de ''regenerar en lugar de rellenar'' y refuerza el posicionamiento de largo plazo.','La elección de bioestimuladores, exosomas, PDRN, PRP o hidrataciones profundas depende de evaluación médica y no debe automatizarse.','{"summary":"Enfoque facial de regeneración, longevidad y sostén biológico.","domain":"DOMAIN_FACIAL","source_treatments":["Bioestimuladores de colágeno","Exosomas","Polinucleótidos / PDRN","PRP","Hidrataciones profundas con AH"],"source_products":["Beauty Maker","Neuro Vital","Astaxantina","Hydrashield","Regushield","Sensishield","SkinRegeneration","UltrAGlow","Cardo mariano 500 mg/120","Anti-hair loss shampoo 150 ml","Spray minoxidil","Nf cap women o men anti-hair"],"source_benefits":["Mejora progresiva de flacidez","Aumento de calidad tisular","Rejuvenecimiento natural"],"source_ideal_profile":["Pacientes +35","Personas que buscan longevidad estética","Pacientes conscientes del proceso"],"source_recommendations":["Acompañar siempre con vitamina C","Integrar detox en pacientes descritos como inflamados"],"source_bias":{"bias":"Esto demora","use":"Posicionarlo como inversión a futuro"},"source_process":["Evaluación","Activación interna","Sesiones regenerativas","Productos","Seguimiento"],"source_objective":"Sostener juventud biológica sin perder naturalidad","source_terms_are_not_canonical_catalog_names":true}'::jsonb,'ACTIVE','ZI_KNOWLEDGE_V1_20260827')
